//! Keys generated by `browntls-crypto`: RSA keys with certificate chains
//! whose signatures the native provider's signing keys make, and P-521 keys
//! (which rcgen with ring cannot generate) for raw public key handshakes.
//!
//! The keys are generated at run time and live only in memory.

use std::sync::{Arc, OnceLock};

use browntls::SignatureScheme;
use browntls::crypto::native;
use browntls::pki_types::{
    CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, PrivateSec1KeyDer, SubjectPublicKeyInfoDer,
};
use browntls::sign::{CertifiedKey, SigningKey};
use browntls_crypto::nist::p521;
use browntls_crypto::rand::OsRng;
use browntls_crypto::rsa::{MAX_MODULUS_BYTES, MAX_PKCS8_PRIVATE_KEY_DER_LEN, RsaPrivateKey};
use rcgen::{ExtendedKeyUsagePurpose, PKCS_RSA_SHA256, PKCS_RSA_SHA384, PKCS_RSA_SHA512};

use super::{Chain, KeyType, issue_chain};

/// An RSA key generated by `browntls-crypto` that signs certificates (for
/// rcgen) through the native provider's [`SigningKey`], with PKCS #1 v1.5
/// and the hash of `alg`.
#[derive(Clone)]
pub struct NativeRsaKey {
    pub pkcs8: Vec<u8>,
    /// The PKCS #1 `RSAPublicKey`: the SubjectPublicKeyInfo's key bits.
    pub rsa_public_key: Vec<u8>,
    pub key: Arc<dyn SigningKey>,
    pub alg: &'static rcgen::SignatureAlgorithm,
}

impl std::fmt::Debug for NativeRsaKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NativeRsaKey")
            .field("alg", &self.alg)
            .finish_non_exhaustive()
    }
}

impl NativeRsaKey {
    /// Generates a key with `browntls-crypto` and loads it with the native
    /// provider's key loader.
    pub fn generate(bits: usize) -> Self {
        let key = RsaPrivateKey::generate(bits, &OsRng).expect("native RSA key generation");
        let mut pkcs8 = vec![0u8; MAX_PKCS8_PRIVATE_KEY_DER_LEN];
        let len = key.to_pkcs8_der(&mut pkcs8).expect("PKCS #8 export");
        pkcs8.truncate(len);
        let mut rsa_public_key = vec![0u8; MAX_MODULUS_BYTES + 32];
        let len = key
            .public_key()
            .to_pkcs1_der(&mut rsa_public_key)
            .expect("public key export");
        rsa_public_key.truncate(len);
        let key = native::KEY_PROVIDER
            .load_private_key(PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(
                pkcs8.clone(),
            )))
            .expect("native provider loads its own RSA key");
        Self {
            pkcs8,
            rsa_public_key,
            key,
            alg: &PKCS_RSA_SHA256,
        }
    }

    /// The same key, signing certificates with `alg`'s hash.
    pub fn with_alg(&self, alg: &'static rcgen::SignatureAlgorithm) -> Self {
        Self {
            alg,
            ..self.clone()
        }
    }

    /// The TLS scheme naming the PKCS #1 v1.5 algorithm `alg` stands for.
    pub fn scheme(&self) -> SignatureScheme {
        if *self.alg == PKCS_RSA_SHA256 {
            SignatureScheme::RSA_PKCS1_SHA256
        } else if *self.alg == PKCS_RSA_SHA384 {
            SignatureScheme::RSA_PKCS1_SHA384
        } else if *self.alg == PKCS_RSA_SHA512 {
            SignatureScheme::RSA_PKCS1_SHA512
        } else {
            panic!("not an RSA PKCS #1 algorithm: {:?}", self.alg)
        }
    }
}

impl rcgen::PublicKeyData for NativeRsaKey {
    fn der_bytes(&self) -> &[u8] {
        &self.rsa_public_key
    }

    fn algorithm(&self) -> &'static rcgen::SignatureAlgorithm {
        self.alg
    }
}

impl rcgen::SigningKey for NativeRsaKey {
    fn sign(&self, msg: &[u8]) -> Result<Vec<u8>, rcgen::Error> {
        let signer = self
            .key
            .choose_scheme(&[self.scheme()])
            .ok_or(rcgen::Error::RemoteKeyError)?;
        assert_eq!(signer.scheme(), self.scheme());
        signer.sign(msg).map_err(|_| rcgen::Error::RemoteKeyError)
    }
}

/// The PKCS #1 v1.5 certificate signature algorithms.
pub const CERT_ALGS: [&rcgen::SignatureAlgorithm; 3] =
    [&PKCS_RSA_SHA256, &PKCS_RSA_SHA384, &PKCS_RSA_SHA512];

/// Two native RSA-2048 keys (CA, end entity), generated once per test binary.
pub fn keys() -> &'static (NativeRsaKey, NativeRsaKey) {
    static KEYS: OnceLock<(NativeRsaKey, NativeRsaKey)> = OnceLock::new();
    KEYS.get_or_init(|| (NativeRsaKey::generate(2048), NativeRsaKey::generate(2048)))
}

/// A chain whose keys come from `browntls-crypto` and whose certificate
/// signatures (CA self-signature and end-entity certificate) are made by the
/// native provider with PKCS #1 v1.5 and `alg`'s hash.
pub fn chain(
    alg: &'static rcgen::SignatureAlgorithm,
    names: &[&str],
    purpose: ExtendedKeyUsagePurpose,
) -> Chain {
    let (ca, ee) = keys();
    chain_with(ca, ee, alg, names, purpose)
}

/// Like [`chain`] with the given CA and end-entity keys (of any size; the
/// chain's `key_type` is then only the key family).
pub fn chain_with(
    ca: &NativeRsaKey,
    ee: &NativeRsaKey,
    alg: &'static rcgen::SignatureAlgorithm,
    names: &[&str],
    purpose: ExtendedKeyUsagePurpose,
) -> Chain {
    let chain = issue_chain(
        KeyType::Rsa2048,
        ca.with_alg(alg),
        ee,
        ee.pkcs8.clone(),
        names,
        purpose,
    );
    // rcgen's SubjectPublicKeyInfo matches the native signing key's own.
    assert_eq!(
        chain.end_entity_spki,
        ee.key.public_key().expect("RSA keys have an SPKI").as_ref()
    );
    chain
}

/// A natively signed server chain for `localhost`.
pub fn server_chain(alg: &'static rcgen::SignatureAlgorithm) -> Chain {
    chain(
        alg,
        &["localhost", "testserver.example"],
        ExtendedKeyUsagePurpose::ServerAuth,
    )
}

/// A natively signed client chain.
pub fn client_chain(alg: &'static rcgen::SignatureAlgorithm) -> Chain {
    chain(
        alg,
        &["client.example"],
        ExtendedKeyUsagePurpose::ClientAuth,
    )
}

/// A P-521 key generated by `browntls-crypto` (SEC 1 DER), for raw public
/// key handshakes, with its SubjectPublicKeyInfo as the native provider
/// computes it.
#[derive(Clone, Debug)]
pub struct P521RawKey {
    pub sec1: Vec<u8>,
    pub spki: Vec<u8>,
}

impl P521RawKey {
    pub fn generate() -> Self {
        let key = p521::SecretKey::generate(&OsRng).expect("P-521 key generation");
        let mut der = [0u8; p521::SEC1_PRIVATE_MAX_LEN];
        let len = key.to_sec1_der(&mut der).expect("SEC 1 export");
        let sec1 = der[..len].to_vec();
        let loaded = native::KEY_PROVIDER
            .load_private_key(PrivateKeyDer::Sec1(PrivateSec1KeyDer::from(sec1.clone())))
            .expect("native provider loads its own P-521 key");
        let spki = loaded.public_key().expect("SPKI").as_ref().to_vec();
        Self { sec1, spki }
    }

    pub fn private_key(&self) -> PrivateKeyDer<'static> {
        PrivateKeyDer::Sec1(PrivateSec1KeyDer::from(self.sec1.clone()))
    }

    /// Serves this key as a raw public key, loaded by `provider`'s key loader.
    pub fn resolver(
        &self,
        provider: &browntls::crypto::CryptoProvider,
    ) -> Arc<super::RawKeyResolver> {
        let key = provider
            .key_provider
            .load_private_key(self.private_key())
            .expect("P-521 key loads");
        Arc::new(super::RawKeyResolver(Arc::new(CertifiedKey::new(
            vec![CertificateDer::from(self.spki.clone())],
            key,
        ))))
    }

    /// Expects this key as the server's raw public key; signatures are
    /// checked with `algs`.
    pub fn server_verifier(
        &self,
        algs: browntls::crypto::WebPkiSupportedAlgorithms,
    ) -> Arc<super::PinnedServerVerifier> {
        Arc::new(super::PinnedServerVerifier {
            expected: CertificateDer::from(self.spki.clone()),
            spki: SubjectPublicKeyInfoDer::from(self.spki.clone()),
            algs,
            raw: true,
        })
    }

    /// Requires this key as the client's raw public key; signatures are
    /// checked with `algs`.
    pub fn client_verifier(
        &self,
        algs: browntls::crypto::WebPkiSupportedAlgorithms,
    ) -> Arc<super::PinnedClientVerifier> {
        Arc::new(super::PinnedClientVerifier {
            expected: CertificateDer::from(self.spki.clone()),
            spki: SubjectPublicKeyInfoDer::from(self.spki.clone()),
            algs,
            mandatory: true,
            hints: Vec::new(),
            raw: true,
        })
    }
}
